<script setup lang="ts">
import { onMounted,reactive,ref } from 'vue'
import { ElDatePicker, ElInputNumber } from 'element-plus'
import PlatformLayout from '../components/PlatformLayout.vue'
import { useApi,money,date,type Row } from '../composables/useApi'
const {api,act}=useApi(),profile=ref<Row>({}),slots=ref<Row[]>([]),loading=ref(false),saving=ref(false),error=ref('')
const form=reactive({bio:'',price:50}),slot=reactive({start:'',end:'',price:50})
const labels:Record<string,string>={NOT_SUBMITTED:'尚未提交',PENDING:'等待审核',APPROVED:'审核通过',REJECTED:'审核未通过'}
async function load(){loading.value=true;error.value='';try{[profile.value,slots.value]=await Promise.all([api('/sitter/profile'),api<Row[]>('/sitter/slots')]);Object.assign(form,{bio:profile.value.BIO??'',price:Number(profile.value.PRICE_CENTS??5000)/100});slot.price=form.price}catch(e){error.value=(e as Error).message}finally{loading.value=false}}
async function save(){if(saving.value)return;saving.value=true;if(await act(()=>api('/sitter/profile','PUT',{bio:form.bio.trim(),priceCents:Math.round(form.price*100)}),'资料已提交，等待管理员审核'))await load();saving.value=false}
async function publish(){if(saving.value)return;saving.value=true;if(await act(()=>api('/slots','POST',{start:slot.start,end:slot.end,priceCents:Math.round(slot.price*100)}),'时段已发布')){slot.start='';slot.end='';await load()}saving.value=false}
async function remove(row:Row){if(await act(()=>api(`/slots/${row.ID}`,'DELETE'),'已撤下时段'))await load()}
onMounted(load)
</script>
<template><PlatformLayout><div class="page-heading"><div><span class="eyebrow">SITTER SPACE</span><h1>服务资料与时段</h1><p>审核通过后发布时段；收到预约后，根据主人上门地址和报价决定接单。</p></div><el-tag>{{ labels[profile.STATUS]||'读取中' }}</el-tag></div><el-alert v-if="error" :title="error" type="error" :closable="false"/><div class="two-columns" v-loading="loading"><section class="business-card"><h3>我的服务资料</h3><el-alert v-if="profile.REVIEW_NOTE" :title="`审核说明：${profile.REVIEW_NOTE}`" :closable="false"/><el-form label-position="top" @submit.prevent="save"><el-form-item label="服务介绍"><el-input v-model="form.bio" type="textarea" :rows="4" maxlength="1000" placeholder="你的照顾经验、服务内容及注意事项"/></el-form-item><el-form-item label="参考报价（元 / 次）"><el-input-number v-model="form.price" :min="1" :max="1000" :precision="2"/></el-form-item><p class="muted">修改资料后将重新审核；已有订单仍可履约。</p><el-button type="primary" native-type="submit" :loading="saving">提交资料审核</el-button></el-form></section><section class="business-card"><h3>发布可约时段</h3><el-alert v-if="profile.STATUS!=='APPROVED'" title="资料审核通过后才能发布时段。" :closable="false" type="info"/><el-form label-position="top" @submit.prevent="publish"><el-form-item label="开始时间"><el-date-picker v-model="slot.start" type="datetime" value-format="YYYY-MM-DDTHH:mm:ssZ" placeholder="选择开始时间"/></el-form-item><el-form-item label="结束时间"><el-date-picker v-model="slot.end" type="datetime" value-format="YYYY-MM-DDTHH:mm:ssZ" placeholder="选择结束时间"/></el-form-item><el-form-item label="本次报价（元）"><el-input-number v-model="slot.price" :min="1" :max="1000" :precision="2"/></el-form-item><p class="muted">服务时长 30 分钟至 4 小时，同一喂养员时段不能重叠。</p><el-button type="primary" native-type="submit" :loading="saving" :disabled="profile.STATUS!=='APPROVED'">发布时段</el-button></el-form></section></div><section class="business-card spaced"><h3>我的时段</h3><el-table :data="slots" empty-text="暂无时段"><el-table-column label="开始时间" min-width="180"><template #default="s">{{ date(s.row.STARTS_AT) }}</template></el-table-column><el-table-column label="结束时间" min-width="180"><template #default="s">{{ date(s.row.ENDS_AT) }}</template></el-table-column><el-table-column label="报价"><template #default="s">{{ money(s.row.PRICE_CENTS) }}</template></el-table-column><el-table-column label="状态"><template #default="s">{{ s.row.WITHDRAWN?'已撤下':s.row.BOOKED?'已预约':'可预约' }}</template></el-table-column><el-table-column label="操作"><template #default="s"><el-button v-if="!s.row.BOOKED&&!s.row.WITHDRAWN" text @click="remove(s.row)">撤下</el-button></template></el-table-column></el-table></section></PlatformLayout></template>
